def _engine_turn_policy(system_prompt: str, *, prompt_format: str = 'text') -> tuple[str | None, str]:
    """Exclude only validated clock/turn values, not arbitrary trusted instructions."""
    if prompt_format == 'aisp_host':
        from .aisp_prompt import policy_fingerprint
        return policy_fingerprint(system_prompt, _engine_turn_policy)
    blocks = []
    normalized = system_prompt
    for name in ('CURRENT TIME', 'EXECUTION CONTEXT'):
        matches = list(re.finditer(r'(?m)^\[' + name + r'\]\n(.*?)(?=\n\n|\Z)', system_prompt, re.S))
        if len(matches) != 1:
            return None, ''
        match = matches[0]
        body = match.group(1)
        if name == 'CURRENT TIME':
            try:
                datetime.fromisoformat(body)
            except ValueError:
                return None, ''
            replacement = '[CURRENT TIME]\n<runtime-clock>'
        else:
            rows = body.splitlines()
            pairs = [line.split(': ', 1) for line in rows]
            if any(len(pair) != 2 or not pair[1] for pair in pairs):
                return None, ''
            fields = dict(pairs)
            allowed = {'turn_id', 'cache_dir', 'cache_name', 'trace_id', 'session_id',
                       'origin_channel', 'entry_mode', 'user_language', 'requested_model'}
            if len(fields) != len(pairs) or not set(fields) <= allowed \
                    or not {'turn_id', 'cache_dir', 'cache_name', 'trace_id', 'session_id'} <= set(fields):
                return None, ''
            replacement = '[EXECUTION CONTEXT]\n' + '\n'.join(
                key + ': ' + ('<runtime-turn>' if key in {'turn_id', 'entry_mode'} else value)
                for key, value in pairs)
        blocks.append(match.group(0))
        normalized = normalized.replace(match.group(0), replacement, 1)
    if '[LOADED AISOP: engine_node.aisop.json]' in system_prompt:
        try:
            from soulrun import host as soulrun_host
            projection = soulrun_host.project_slim_policy(normalized, cache_dir=fields['cache_dir'],
                                                         entry_mode=fields.get('entry_mode'))
            if not isinstance(projection, dict) or not isinstance(projection.get('policy_text'), str) \
                    or not isinstance(projection.get('runtime_fragment'), str) \
                    or not re.fullmatch(r'[0-9a-f]{64}', str(projection.get('source_digest') or '')):
                return None, ''
            normalized = projection['policy_text']
            blocks.append(projection['runtime_fragment'])
        except Exception:
            return None, ''
    if '[EXECUTE ENGINE ENTRY]\n' not in system_prompt:
        return None, ''
    return hashlib.sha256(normalized.encode()).hexdigest(), '\n\n'.join(blocks)
